"""Group Z-Anatomy object names (from blend_names.py json) into brain regions -> MESH_LIST.md. python -I mesh_list.py names.json out.md"""
import json, re, sys, collections
names = json.load(open(sys.argv[1]))['OB']
base = collections.defaultdict(set)
for n in names:
    m = re.match(r'^(.*?)(?:\.([a-z]{1,2}))?$', n)
    b, s = m.group(1).strip(), m.group(2) or ''
    base[b].add(s)
R = collections.OrderedDict([
 ('Cortex: gyri / lobes / areas', r'gyrus|lobule|operculum|insula|cortex|lobe of (cerebral|brain)|(frontal|parietal|occipital|temporal|limbic) lobe|precuneus|cuneus|uncus|Brodmann|paracentral|orbital part|pole of|isthmus'),
 ('Cortex: sulci / fissures', r'sulcus|fissure(?! of (lung|liver))'),
 ('Ventricles / CSF / meninges', r'ventric(le|ular)(?! of heart)|aqueduct|choroid|cistern|foramen of (Monro|Magendie|Luschka)|interventricular foramen|subarachnoid|dura|arachnoid|pia mater|falx|tentorium|dural|septum pellucidum|recess of (third|fourth)|cerebrospinal'),
 ('Basal ganglia / striatum', r'caudate nucleus|putamen|globus pallidus|lentiform|corpus striatum|nucleus accumbens|claustrum|substantia nigra|subthalamic|striatum|pallid'),
 ('Thalamus / epithalamus / hypothalamus / pituitary / pineal', r'thalam|hypothalam|geniculate|pineal|pituitary|hypophysis|mammillary|habenula|infundibul|tuber cinereum|optic chiasm|preoptic|paraventricular|supraoptic|arcuate nucleus|septal'),
 ('Limbic / white matter commissures & tracts (cerebrum)', r'hippocamp|amygdal|fornix|cingul|parahippocamp|dentate|corpus callosum|anterior commissure|posterior commissure|internal capsule|external capsule|extreme capsule|corona radiata|optic (radiation|tract)|uncinate|arcuate fasc|longitudinal fasc|fasciculus|olfactory|stria|white matter|commissure|forceps|tapetum|cingulum|capsule'),
 ('Brainstem: midbrain / pons / medulla (external + internal)', r'midbrain|pons|pontine|medulla|brainstem|brain stem|colliculus|tegment|cerebral peduncle|olive|olivary|pyramid|decussation|interpeduncular|trapezoid|reticular|raphe|lemnisc|periaqueductal|red nucleus|tectum|tectal|obex|area postrema|rhomboid|facial colliculus|tuberculum|funiculus|trigone|floor of fourth'),
 ('Cranial nerve nuclei', r'nucleus (of|solitar|ambig|dorsal|spinal)|(abducens|oculomotor|trochlear|trigeminal|facial|vestibular|cochlear|hypoglossal|glossopharyngeal|vagus|vagal|accessory|salivatory|motor|mesencephalic|sensory|principal|edinger|solitary|ambiguus) nucle|nucleus of (the )?(trigeminal|hypoglossal|abducens|facial|trochlear|oculomotor)|vestibular nuclei|cochlear nuclei|salivatory'),
 ('Cranial nerves (I-XII) and roots', r'(olfactory|optic|oculomotor|trochlear|trigeminal|abducens|facial|vestibulocochlear|vestibular|cochlear|glossopharyngeal|vagus|accessory|hypoglossal) nerve|cranial nerve|\((I|II|III|IV|V|VI|VII|VIII|IX|X|XI|XII)\)|ganglion(?! of sympathetic)|rootlet'),
 ('Cerebellum', r'cerebell|vermis|flocculus|tonsil of|nodulus|folium|tuber of vermis|declive|culmen|lingula|uvula|pyramid of vermis|dentate nucleus|emboliform|globose|fastigial|peduncle'),
 ('Spinal cord (grey/white matter, tracts, roots)', r'spinal cord|horn of spinal|funiculus|tract|fasciculus (gracilis|cuneatus)|gracile|cuneate|cauda equina|conus medullaris|filum terminale|central canal|spinal nerve|root of spinal|dorsal root|substantia gelatinosa|clarke|lissauer|spinal ganglion|column of spinal'),
 ('Arteries (brain / cerebral supply)', r'cerebral artery|cerebellar artery|basilar|vertebral artery|internal carotid|circle of willis|cerebral arterial|communicating artery|choroidal|striate|labyrinthine|pontine arter|spinal artery|artery of (central|precentral|postcentral|angular|cerebral)|branch to|carotid|ophthalmic artery|meningeal artery|callosomarginal|pericallosal|recurrent artery|lenticulostriate|thalamoperforating|Heubner|insular|orbitofrontal|prefrontal|opercul'),
 ('Veins / dural venous sinuses', r'sinus(?! of (kidney|tarsus|pulmonary|aorta|epididymis|venarum))|cerebral vein|vein of (galen|labb|trolard)|great cerebral|internal cerebral vein|basal vein|emissary|bridging|diploic|jugular'),
])
out = ['# MESH_LIST: Z-Anatomy (Startup.blend v3.05) brain-related objects', '',
 'Generated by tools/atlas/blend_names.py + mesh_list.py from Z-Anatomy.zip/Startup.blend (7,184 objects total).',
 'Name suffixes: .l/.r = left/right; .g/.j/.t/.i/.s are Z-Anatomy structural variants (.g commonly a group/parent, .j/.t joined/typical-part duplicates). Verify in Blender before relying on them.',
 'Keyword classification is heuristic, so entries can sit in the wrong group, and some structures appear in several groups.', '']
seen = set(); tot = 0
for g, rx in R.items():
    c = re.compile(rx, re.I)
    items = sorted(b for b in base if c.search(b) and not re.search(r'tibia|femur|femoral|plantar|palmar|digit|humer|radi(al|us)|ulnar|fibul|brachial plexus|lung|bronch|heart|cardiac|kidney|renal|liver|hepatic|muscle|tendon|bone|joint|ligament|gland|hallucis|auricul|thyroid|larynx|laryn|vertebra|tarsal|carpal|metacarp|metatars|phalan|pelvi|femor|gastric|intestin|colic|ileo|mesenter|uter|ovar|testic|prostat|vagin|penis|scrot|spleen|pancrea|diaphragm|thorac(ic|o)|axillar|inguinal|popliteal|pharyn|esophag|tracheal|bladder', b, re.I))
    out.append(f'## {g} ({len(items)})'); out.append('')
    for b in items:
        out.append(f'- {b}  [{",".join(sorted(x for x in base[b] if x)) or "-"}]'); seen.add(b)
    out.append('')
    tot += len(items)
open(sys.argv[2], 'w', encoding='utf8').write('\n'.join(out))
print(tot, len(seen), len(base))
